mapper.select:
select t1.id, t1.name, t1.room, t1.begin_date, t1.end_date, t1.subject, t1.create_time, t1.update_time, t2.name as master_name from clazz t1 left join emp t2 on t1.master_id = t2.id


        t1.name like CONCAT('%', #{name}, '%')


         and t1.begin_date >= #{begin}


         and t1.end_date <= #{end}
